      },
      "Message": {
        "User": {
          "userId": "eid_bf6c7f21",
          "timestamp": "2026-06-27T19:26:00",
          "text": "That's a big deal, especially for users in fast-paced environments. 🚀 How about their language support? Which languages are they missing?",
          "utterranceID": "20260810-3-76374"
        },
        "Reactions": []
      },
      "ThreadReplies": [],
      "id": "20260810-3-76374"
