        "channelID": "ch-force-bcdfce"
      },
      "Message": {
        "User": {
          "userId": "eid_5318af37",
          "timestamp": "2026-06-27T19:31:00",
          "text": "Alice, they primarily focus on major global languages like English, Spanish, and Mandarin. However, they lack support for many regional languages, which could limit their reach in diverse markets.",
          "utterranceID": "20260810-4-72aee"
        },
        "Reactions": []
      },
      "ThreadReplies": [],
      "id": "20260810-4-72aee"
    },
